import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:smart_receipt/ocr/tfidf_classifier.dart';
import 'package:smart_receipt/services/text_normalizer.dart';

/// Parity tests between the Python training pipeline and the Dart runtime.
///
/// The model is trained in Python (`ML/training.py`) and executed in Dart
/// (`tfidf_classifier.dart`). Any divergence — a different n-gram split, a
/// rounding bug, a missing normalization rule — silently costs accuracy on
/// device while every unit test keeps passing. These fixtures are generated by
/// `ML/make_fixtures.py` from the shipped model, so the comparison is exact.
///
/// Regenerate after retraining:
/// ```bash
/// cd ML && python make_fixtures.py
/// ```
void main() {
  late Map<String, dynamic> preprocessingFixture;
  late Map<String, dynamic> predictionFixture;

  setUpAll(() {
    preprocessingFixture = jsonDecode(
      File('test/fixtures/preprocessing_parity.json').readAsStringSync(),
    ) as Map<String, dynamic>;
    predictionFixture = jsonDecode(
      File('test/fixtures/model_parity_predictions.json').readAsStringSync(),
    ) as Map<String, dynamic>;
  });

  test('preprocessing matches ML/preprocessing.py exactly', () {
    final IndonesianTextPreprocessor preprocessor = IndonesianTextPreprocessor()
      ..loadFromMap(
        jsonDecode(
              File('assets/text_normalization_id.json').readAsStringSync(),
            )
            as Map<String, dynamic>,
      );

    final List<dynamic> cases = preprocessingFixture['cases'] as List<dynamic>;
    expect(cases.length, greaterThanOrEqualTo(100));

    final List<String> mismatches = <String>[];
    for (final dynamic entry in cases) {
      final Map<String, dynamic> c = entry as Map<String, dynamic>;
      final String raw = c['raw'] as String;
      final String expected = c['expected'] as String;
      final String actual = preprocessor.normalize(raw);
      if (actual != expected) {
        mismatches.add('"$raw"\n  dart:   "$actual"\n  python: "$expected"');
      }
    }

    expect(
      mismatches,
      isEmpty,
      reason:
          '${mismatches.length}/${cases.length} inputs diverge between Dart '
          'and Python preprocessing. First few:\n${mismatches.take(5).join('\n')}',
    );
  });

  test('model predictions match ML/make_fixtures.py exactly', () {
    final TfidfNaiveBayesEngine engine = TfidfNaiveBayesEngine()
      ..loadFromJsonString(
        File('assets/model_kategori_produk.json').readAsStringSync(),
      );

    expect(
      engine.reviewMargin,
      (predictionFixture['reviewMargin'] as num).toDouble(),
    );

    final List<dynamic> cases = predictionFixture['cases'] as List<dynamic>;
    expect(cases.length, greaterThanOrEqualTo(100));

    final List<String> mismatches = <String>[];
    for (final dynamic entry in cases) {
      final Map<String, dynamic> c = entry as Map<String, dynamic>;
      final String text = c['text'] as String;
      final TfidfPrediction prediction = engine.predict(text);

      if (prediction.topLabel != c['topLabel']) {
        mismatches.add('"$text": topLabel dart=${prediction.topLabel} '
            'python=${c['topLabel']}');
        continue;
      }
      if (prediction.label != c['label']) {
        mismatches.add('"$text": label dart=${prediction.label} '
            'python=${c['label']}');
        continue;
      }
      if (prediction.categoryId != c['categoryId']) {
        mismatches.add('"$text": categoryId dart=${prediction.categoryId} '
            'python=${c['categoryId']}');
        continue;
      }
      final double expectedMargin = (c['margin'] as num).toDouble();
      if ((prediction.margin - expectedMargin).abs() > 1e-4) {
        mismatches.add('"$text": margin dart=${prediction.margin} '
            'python=$expectedMargin');
      }
    }

    expect(
      mismatches,
      isEmpty,
      reason:
          '${mismatches.length}/${cases.length} predictions diverge between '
          'Dart and Python. First few:\n${mismatches.take(5).join('\n')}',
    );
  });
}
